import fs from "node:fs";
import path from "node:path";
import { randomUUID } from "node:crypto";

export const name = "building-loop-real-audit-witness";
export const inject = ["agentPresets", "agents", "sessions", "sessionController", "tools", "llm"];

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
const home = process.env.BUILDING_LOOP_REAL_RUN;
const route = { provider: "deepseek-official", model: "deepseek-flash", reasoningEffort: "off" };
const tracked = new Set([
  "turn/start", "turn/end", "step/start", "step/end", "user/message",
  "assistant/message", "assistant/attempt", "tool/call", "tool/result",
  "subagent/catalog", "subagent/descriptor", "agent/inbox/claimed",
  "agent/inbox/inserted", "session/model",
]);
const allowed = new Set(["read", "write", "edit", "skill", "subagent", "send_message",
  "list_agents", "wait_agent", "list_subagent_models", "todo_write", "glob"]);
const fileTools = new Set(["read", "write", "edit"]);

function json(data) {
  const key = process.env.DEEPSEEK_API_KEY;
  const text = JSON.stringify(data, (_key, value) => typeof value === "bigint" ? value.toString() : value);
  return key ? text.replaceAll(key, "[redacted]") : text;
}

function append(name, data) {
  fs.appendFileSync(path.join(home, name), json({ time: Date.now(), ...data }) + "\n", "utf8");
}

function finished(data) {
  fs.writeFileSync(path.join(home, "finished.json"), json(data) + "\n", "utf8");
}

function inside(root, target) {
  const relative = path.relative(root, target);
  return relative !== ".." && !relative.startsWith(".." + path.sep) && !path.isAbsolute(relative);
}

export function apply(ctx) {
  const groups = new Map();
  const identities = new Map();
  let active = null;
  let initiated = false;
  const progress = data => append("progress.jsonl", data);
  const scopeOf = sessionId => identities.get(sessionId) ?? active;

  ctx.tools.guard(exec => {
    if (!exec.agent) return "Fixture tools require an agent.";
    const group = groups.get(scopeOf(exec.agent.id));
    if (!group) return "Fixture is inactive.";
    const args = exec.arguments ?? {};
    let denial;
    if (!allowed.has(exec.name)) {
      denial = "Use only the workspace file, skill and native subagent tools in this fixture.";
    } else if (fileTools.has(exec.name)) {
      const candidate = path.resolve(group.workspace, typeof args.file_path === "string" ? args.file_path : "");
      const skillRoot = path.join(home, "isolated-home", "profiles", "web", "node_modules",
        "dsh-building-loop", "skills");
      if (!(inside(group.workspace, candidate) || exec.name === "read" && inside(skillRoot, candidate))) {
        denial = "The test permits file access only inside its fixture or bundled skill documents.";
      } else if (exec.name !== "read" && !group.released && path.relative(group.workspace, candidate).replaceAll("\\", "/").toLowerCase() === "module/candidate.md") {
        denial = "The imported first-review fixture is locked until the first rejection.";
      }
    } else if (exec.name === "glob") {
      const target = path.resolve(group.workspace, args.path ?? "");
      const pattern = typeof args.pattern === "string" ? args.pattern.replaceAll("\\", "/") : "";
      if (!inside(group.workspace, target) || !pattern || path.isAbsolute(pattern) || /(^|\/)\.\.(\/|$)|:/.test(pattern)) {
        denial = "Glob must remain inside the fixture workspace.";
      }
    } else if (exec.name === "skill" && !["project-index", "dispatch-protocol"].includes(args.name)) {
      denial = "Use the two building-loop skills for this test.";
    } else if (exec.name === "subagent") {
      if (args.cwd && path.resolve(group.workspace, args.cwd) !== group.workspace) {
        denial = "Subagents must stay in the same fixture workspace.";
      } else if (args.provider && args.provider !== route.provider || args.model && args.model !== route.model) {
        denial = "Both arms and every role must use the same test model.";
      } else if (group.ids.size >= 5) {
        denial = "This small fixture has a four-child safety budget.";
      }
    }
    if (denial) {
      append("events.jsonl", { group: group.name, sid: exec.agent.id, type: "fixture/denied",
        data: { name: exec.name, path: args.file_path ?? args.cwd ?? args.path, reason: denial } });
    }
    return denial;
  });

  ctx.on("session/event", (session, event) => {
    if (!tracked.has(event.type)) return;
    const label = scopeOf(session.id);
    const group = groups.get(label);
    if (!group) return;
    identities.set(session.id, label);
    group.ids.add(session.id);
    group.lastEvent = Date.now();
    const data = event.type === "assistant/message"
      ? { turn: event.data.turn, step: event.data.step, usage: event.data.usage,
          source: { provider: event.data.message?.source?.provider, model: event.data.message?.source?.model },
          content: event.data.message?.content?.filter(block => block.type !== "thinking") }
      : event.type === "assistant/attempt"
        ? { turn: event.data.turn, step: event.data.step, stream: event.data.stream }
        : event.data;
    append("events.jsonl", { group: label, sid: session.id, seq: event.seq, type: event.type, data });
    if (event.type === "tool/result" && !group.released) {
      const receipt = path.join(group.workspace, "records", "audit-first.json");
      try {
        if (fs.existsSync(receipt) && JSON.parse(fs.readFileSync(receipt, "utf8").replace(/^\uFEFF/, "")).decision === "reject") {
          fs.copyFileSync(path.join(home, "sealed-timing.csv"), path.join(group.workspace, "module", "timing.csv"), fs.constants.COPYFILE_EXCL);
          group.released = true;
          append("events.jsonl", { group: label, sid: session.id, type: "fixture/evidence-released", data: { after: "audit-first reject" } });
          progress({ group: label, event: "first-rejection-observed" });
        }
      } catch (error) {
        if (!(error instanceof SyntaxError)) progress({ group: label, event: "fixture-error", error: String(error) });
      }
    }
    if (event.type === "step/start") group.steps++;
    if (event.type === "subagent/catalog") {
      identities.set(event.data.childId, label);
      group.ids.add(event.data.childId);
      progress({ group: label, event: "child", sid: event.data.childId, label: event.data.label });
    }
    if (event.type === "turn/end") {
      const reason = event.data?.reason?.kind ?? "unknown";
      if (reason === "error" || reason === "blocked" || reason === "max-tokens") {
        progress({ group: label, event: "turn-end", sid: session.id, reason, detail: event.data?.reason?.code });
      }
    }
  });

  async function allIdle(group) {
    const agents = [...group.ids].map(id => ctx.agents.get(id)).filter(Boolean);
    return Promise.race([Promise.all(agents.map(agent => agent.whenIdle())).then(() => true), sleep(550).then(() => false)]);
  }

  async function runGroup(name) {
    const directory = path.join(home, name);
    const group = { name, workspace: path.join(directory, "workspace"), ids: new Set(), steps: 0, lastEvent: Date.now() };
    groups.set(name, group);
    active = name;
    const started = Date.now();
    const { sessionId } = await ctx.sessionController.create({ cwd: group.workspace, agentPreset: "building-loop" });
    group.root = sessionId;
    group.ids.add(sessionId);
    identities.set(sessionId, name);
    const agent = ctx.agents.get(sessionId);
    await ctx.sessionController.selectModel({ sessionId, ...route });
    const declared = ctx.tools.schemas(agent).map(definition => definition.name);
    progress({ group: name, event: "start", sid: sessionId, tools: declared.filter(tool => allowed.has(tool)) });
    const requestId = randomUUID();
    await ctx.sessionController.prompt({
      sessionId, requestId, clientTimeZone: "Asia/Shanghai",
      content: [{ type: "text", text: fs.readFileSync(path.join(directory, "prompt.txt"), "utf8") }],
    }, AbortSignal.timeout(10000));
    let end = "deadline";
    while (Date.now() - started < 260000) {
      if (group.steps > 64) {
        end = "step-budget";
        break;
      }
      if (await allIdle(group)) {
        const hasFinal = fs.existsSync(path.join(group.workspace, "records", "audit-final.json"));
        const hasLedger = fs.existsSync(path.join(group.workspace, "ledger.md"));
        if (hasFinal && hasLedger && Date.now() - group.lastEvent > 1800) {
          end = "artifacts-present";
          break;
        }
        if (Date.now() - group.lastEvent > 14000) {
          end = "idle-without-all-artifacts";
          break;
        }
      }
      await sleep(600);
    }
    const result = { group: name, event: "finish", sid: sessionId, end, wallMs: Date.now() - started,
      steps: group.steps, members: [...group.ids] };
    progress(result);
    fs.writeFileSync(path.join(directory, "host-result.json"), json(result) + "\n", "utf8");
    active = null;
    if (end === "deadline" || end === "step-budget") throw new Error(name + " exceeded its test budget");
    return result;
  }

  const timer = setInterval(async () => {
    if (initiated) return;
    try {
      const preset = (await ctx.agentPresets.list()).find(row => row.id === "building-loop");
      if (!preset) return;
      initiated = true;
      if (preset.broken) throw new Error("building-loop preset is broken");
      const info = await ctx.llm.resolveModelInfo(route.provider, route.model);
      progress({ event: "route-ready", provider: route.provider, model: route.model, title: info?.name });
      const reuse = await runGroup("reuse");
      if (reuse.steps === 0) throw new Error("No model step ran in the first arm");
      const fresh = await runGroup("fresh");
      finished({ status: "observed", groups: [reuse, fresh] });
    } catch (error) {
      initiated = true;
      progress({ event: "error", error: String(error) });
      finished({ status: "error", error: String(error) });
    }
  }, 300);
  ctx.on("dispose", () => clearInterval(timer));
}

from collections import Counter, defaultdict
from pathlib import Path
import json
import os
import re
import sys

run = Path(sys.argv[1]).resolve(strict=True)


def rows(file):
    if not file.exists():
        return []
    output = []
    for line in file.read_text(encoding="utf-8").splitlines():
        try:
            output.append(json.loads(line))
        except json.JSONDecodeError:
            break
    return output


def load(file):
    if not file.is_file():
        return None
    try:
        return json.loads(file.read_text(encoding="utf-8-sig"))
    except json.JSONDecodeError:
        return {"parseError": True}


def tool_arguments(event):
    value = event.get("data", {}).get("arguments") or {}
    if isinstance(value, str):
        try:
            return json.loads(value)
        except json.JSONDecodeError:
            return {}
    return value


def file_path(raw, root):
    if not isinstance(raw, str):
        return None
    full = (root / raw).resolve()
    if full.is_relative_to(root):
        return full.relative_to(root).as_posix()
    if "/node_modules/dsh-building-loop/skills/" in full.as_posix():
        return "@skill/" + full.as_posix().split("/node_modules/dsh-building-loop/skills/", 1)[1]
    return "@outside"


def usage(messages):
    present = [e for e in messages if e.get("data", {}).get("usage") is not None]
    counters = Counter()
    mismatch = 0
    routes = set()
    for e in present:
        d = e["data"]
        u = d["usage"]
        model = d.get("source", {})
        routes.add((model.get("provider"), model.get("model")))
        for k in ("inputTokens", "outputTokens", "cacheReadTokens", "cacheWriteTokens", "totalTokens"):
            counters[k] += u.get(k, 0)
        if sum(u.get(k, 0) for k in ("inputTokens", "outputTokens", "cacheReadTokens", "cacheWriteTokens")) != u.get("totalTokens", -1):
            mismatch += 1
    prompt = sum(counters[k] for k in ("inputTokens", "cacheReadTokens", "cacheWriteTokens"))
    return {"requestsWithUsage": len(present), "promptTokens": prompt, "uncachedInput": counters["inputTokens"],
            "outputTokens": counters["outputTokens"], "cacheReadTokens": counters["cacheReadTokens"],
            "cacheWriteTokens": counters["cacheWriteTokens"], "totalTokens": counters["totalTokens"],
            "hitRate": counters["cacheReadTokens"] / prompt if prompt else None,
            "usageRowsMismatch": mismatch, "routes": sorted(routes),
            "assistantMessagesWithoutUsage": len(messages) - len(present)}


all_events = rows(run / "events.jsonl")
progress = rows(run / "progress.jsonl")
metadata = load(run / "run.json")


def group_stats(name):
    group_dir = run / name
    workspace = group_dir / "workspace"
    start = next((e for e in progress if e.get("event") == "start" and e.get("group") == name), None)
    end = load(group_dir / "host-result.json")
    events = [e for e in all_events if e.get("group") == name]
    if start is None:
        return {"started": False}
    root = start["sid"]
    messages = [e for e in events if e["type"] == "assistant/message"]
    results = {(e["sid"], e["data"].get("message", {}).get("toolCallId")): e for e in events if e["type"] == "tool/result"}
    labels = {e["data"]["childId"]: e["data"]["label"] for e in events if e["type"] == "subagent/catalog" and e["sid"] == root}
    roles = {root: "coordinator", **labels}
    calls = []
    for e in events:
        if e["type"] != "tool/call":
            continue
        d = e["data"]
        args = tool_arguments(e)
        r = results.get((e["sid"], d.get("callId")))
        result = r["data"].get("message", {}) if r else {}
        calls.append({**e, "tool": d.get("name"), "args": args, "ok": (not result.get("isError", False)) if r else None,
                      "file": file_path(args.get("file_path"), workspace)})
    writes = [e for e in calls if e["tool"] in ("write", "edit") and e["ok"]]
    candidate = [e for e in writes if e["file"] == "module/candidate.md"]
    first = [e for e in writes if e["file"] == "records/audit-first.json"]
    final = [e for e in writes if e["file"] == "records/audit-final.json"]
    seed = run / "seed-candidate.md"
    seeded = seed.is_file()
    first_draft = candidate[0] if candidate and not seeded else None
    staged_reader = next((e for e in calls if e["tool"] == "read" and e["ok"] and e["file"] == "module/candidate.md"
                          and e["sid"] in labels and (not first or e["time"] < first[0]["time"])
                          and not re.search("核验|验收|审核|review|audit", labels[e["sid"]], re.I)), None)
    second_candidates = [e for e in (candidate if seeded else candidate[1:]) if first and e["time"] >= first[0]["time"]]
    last_draft = second_candidates[-1] if second_candidates else None
    draft_path = workspace / "module/candidate.md"
    draft = draft_path.read_text(encoding="utf-8-sig") if draft_path.is_file() else ""
    start_writer = staged_reader["sid"] if seeded and staged_reader else first_draft["sid"] if first_draft else None
    end_writer = last_draft["sid"] if last_draft else None
    root_calls = [e for e in calls if e["sid"] == root]
    root_skills = [e["args"].get("name") for e in root_calls if e["tool"] == "skill" and e["ok"]]
    root_paths = {"AGENTS.md", "DISPATCH.md", "PROJECT.md", "ledger.md"}
    def permitted_root_access(c):
        return (c["file"] == "ledger.md") if c["tool"] in ("write", "edit") else (
            c["file"] in root_paths or c["file"].startswith(("records/", "@skill/")))
    scope_exceptions = [
        {"tool": e["tool"], "file": e["file"], "ok": e["ok"], "seq": e["seq"]}
        for e in root_calls if e["file"] is not None and not permitted_root_access(e)
    ]
    searches = []
    for e in root_calls:
        if e["tool"] not in ("glob", "grep", "pwsh", "bash"):
            continue
        result = results.get((e["sid"], e["data"].get("callId")))
        payload = result["data"].get("message", {}).get("content") if result else None
        searches.append({"tool": e["tool"], "args": e["args"], "ok": e["ok"], "seq": e["seq"], "result": payload,
                         "modulePathsReturned": bool(e["ok"] and re.search(r"module[\\/]", json.dumps(payload, ensure_ascii=False)))})
    first_result = load(workspace / "records/audit-first.json")
    final_result = load(workspace / "records/audit-final.json")
    ledger_file = workspace / "ledger.md"
    ledger = ledger_file.read_text(encoding="utf-8-sig") if ledger_file.is_file() else None
    reassign = next((e for e in root_calls if e["tool"] == "send_message" and e["ok"] and
                     e["args"].get("agent_id") == end_writer and first and e["time"] >= first[0]["time"]), None)
    round2_usage = None
    if end_writer:
        if end_writer == start_writer and reassign:
            second_turn = next((e for e in events if e["sid"] == end_writer and e["type"] == "turn/start" and e["time"] >= reassign["time"]), None)
            if second_turn:
                round2_usage = usage([e for e in messages if e["sid"] == end_writer and e["time"] >= second_turn["time"]])
        elif end_writer != start_writer:
            round2_usage = usage([e for e in messages if e["sid"] == end_writer])
    disallowed_early_source = [
        {"sid": e["sid"], "role": roles.get(e["sid"]), "seq": e["seq"]}
        for e in calls if e["tool"] == "read" and e["file"] == "module/timing.csv" and e["ok"]
        and (not first or e["time"] < first[0]["time"])
    ]
    first_text = seed.read_text(encoding="utf-8-sig") if seeded else first_draft["args"].get("content", "") if first_draft else ""
    def normalized(items):
        return {str(x).upper() for x in items or []} if isinstance(items, list) else set()
    first_unsupported = normalized((first_result or {}).get("unsupported"))
    first_audit_prompt = next((e["args"].get("prompt", "") for e in root_calls if e["tool"] == "subagent" and e["ok"]
                               and "audit-first.json" in e["args"].get("prompt", "")), "")
    backup = workspace / "module/candidate.previous.md"
    return {
        "started": True, "root": root, "host": end, "children": labels, "steps": sum(e["type"] == "step/start" for e in events),
        "firstDraftPreservedUncited25": "25%" in first_text and "timing.csv" not in first_text
                                       and (not seeded or not any(not first or e["time"] < first[0]["time"] for e in candidate)),
        "firstAudit": first_result, "firstAuditWriter": first[-1]["sid"] if first else None,
        "firstRejectsC2": bool(first_result and str(first_result.get("decision", "")).lower() == "reject" and "C2" in first_unsupported),
        "firstAuditPromptContainsAnswer": bool(re.search(r"(?:25|20)\s*%|C2[^。\n]{0,12}(?:缺出处|无出处|无来源)", first_audit_prompt)) if first_audit_prompt else None,
        "finalAudit": final_result, "finalAuditWriter": final[-1]["sid"] if final else None,
        "sameAuditor": bool(first and final and first[-1]["sid"] == final[-1]["sid"]),
        "finalSupportsCorrected20": "20%" in draft and "timing.csv" in draft and "25%" not in draft,
        "firstExecutor": start_writer, "secondExecutor": end_writer,
        "rootResentToExecutor": reassign["args"].get("agent_id") if reassign else None,
        "executorReused": start_writer == end_writer if start_writer and end_writer else None,
        "backupMatchesFirstDraft": backup.is_file() and backup.read_text(encoding="utf-8-sig") == first_text,
        "candidateLogPresent": (workspace / "changes/module/candidate.md.md").is_file(),
        "ledger": ledger, "coordinatorScopeExceptions": scope_exceptions, "coordinatorSearches": searches,
        "earlyTimingReads": disallowed_early_source, "coordinatorSkills": root_skills,
        "toolDenials": dict(Counter(e["data"].get("name") for e in events if e["type"] == "fixture/denied")),
        "rootTurns": [e["data"].get("reason") for e in events if e["sid"] == root and e["type"] == "turn/end"],
        "assistantAttempts": sum(e["type"] == "assistant/attempt" for e in events),
        "armUsage": usage(messages), "round2ExecutorUsage": round2_usage,
        "sessionUsage": [{"sid": sid, "role": role, **usage([e for e in messages if e["sid"] == sid])} for sid, role in roles.items()],
    }


report = {"run": metadata, "nativeStatus": load(run / "finished.json"),
          "reuse": group_stats("reuse"), "fresh": group_stats("fresh")}
if "--write" in sys.argv[2:]:
    (run / "audit-summary.json").write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(json.dumps(report, ensure_ascii=False, indent=2))

import fs from "node:fs";
import path from "node:path";
import { randomUUID } from "node:crypto";

export const name = "building-loop-real-audit-witness";
export const inject = ["agentPresets", "agents", "sessions", "sessionController", "tools", "llm", "systemPrompt"];

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
const home = process.env.BUILDING_LOOP_REAL_RUN;
const presetId = process.env.BUILDING_LOOP_GOV_PRESET ?? "building-loop";
const route = { provider: "deepseek-official", model: "deepseek-flash", reasoningEffort: "off" };
const tracked = new Set([
  "turn/start", "turn/end", "step/start", "step/end", "user/message",
  "assistant/message", "assistant/attempt", "tool/call", "tool/result",
  "subagent/catalog", "subagent/descriptor", "agent/inbox/claimed",
  "agent/inbox/inserted", "session/model",
]);
const allowed = new Set(["read", "write", "edit", "skill", "subagent", "send_message",
  "list_agents", "wait_agent", "list_subagent_models", "todo_write", "glob", "grep", "pwsh", "building_loop", "building_loop_file"]);


function json(data) {
  const key = process.env.DEEPSEEK_API_KEY;
  const text = JSON.stringify(data, (_key, value) => typeof value === "bigint" ? value.toString() : value);
  return key ? text.replaceAll(key, "[redacted]") : text;
}

function append(name, data) {
  fs.appendFileSync(path.join(home, name), json({ time: Date.now(), ...data }) + "\n", "utf8");
}

function finished(data) {
  fs.writeFileSync(path.join(home, "finished.json"), json(data) + "\n", "utf8");
}

function inside(root, target) {
  const relative = path.relative(root, target);
  return relative !== ".." && !relative.startsWith(".." + path.sep) && !path.isAbsolute(relative);
}

export function apply(ctx) {
  const groups = new Map();
  const identities = new Map();
  let active = null;
  let initiated = false;
  const progress = data => append("progress.jsonl", data);
  const scopeOf = sessionId => identities.get(sessionId) ?? active;

  ctx.on("llm/stream", (options, next) => {
    const sid = options.sessionId;
    const group = groups.get(scopeOf(sid));
    if (sid && group) {
      const payload = JSON.stringify(options.messages);
      const marker = [...payload.matchAll(/building-loop role=([a-z-]+) phase=([a-z-]+)/g)].at(-1);
      append("events.jsonl", { group: group.name, sid, type: "fixture/request", data: {
        role: marker?.[1], phase: marker?.[2],
        unapprovedInstruction: payload.includes("TEST_ONLY_UNAUTHORIZED_INSTRUCTION_96CD8A"),
      } });
    }
    return next();
  });

  ctx.on("session/event", (session, event) => {
    if (!tracked.has(event.type)) return;
    const label = scopeOf(session.id);
    const group = groups.get(label);
    if (!group) return;
    identities.set(session.id, label);
    group.ids.add(session.id);
    group.lastEvent = Date.now();
    const data = event.type === "assistant/message"
      ? { turn: event.data.turn, step: event.data.step, usage: event.data.usage,
          source: { provider: event.data.message?.source?.provider, model: event.data.message?.source?.model },
          content: event.data.message?.content?.filter(block => block.type !== "thinking") }
      : event.type === "assistant/attempt"
        ? { turn: event.data.turn, step: event.data.step, stream: event.data.stream }
        : event.data;
    append("events.jsonl", { group: label, sid: session.id, seq: event.seq, type: event.type, data });
    if (event.type === "tool/result" && !group.released) {
      const receipt = path.join(group.workspace, "records", "audit-first.json");
      try {
        if (fs.existsSync(receipt) && JSON.parse(fs.readFileSync(receipt, "utf8").replace(/^\uFEFF/, "")).decision === "reject") {
