      }
      const result = event.data.message.content?.find(item => item.type === "text")?.text;
      if (result?.includes('"phase":"ledger-review"') && !group.ledgerProbe) {
        group.ledgerProbe = true;
        group.probes ??= [];
        group.probes.push(negativeProbe(ctx.agents.get(group.root), group, "building_loop_ledger",
          { action: "review", unit: "K01", note: "负向探针，尝试跳过账本读取。", decisions: [] }, "读取最新账本"));
      }
    }
    if (event.type === "tool/result" && !group.released) {
      const receipt = path.join(group.workspace, "records", "audit-first.json");
      try {
        if (fs.existsSync(receipt) && JSON.parse(fs.readFileSync(receipt, "utf8").replace(/^\uFEFF/, "")).decision === "reject") {
          fs.copyFileSync(path.join(home, "sealed-timing.csv"), path.join(group.workspace, "module", "timing.csv"), fs.constants.COPYFILE_EXCL);
          group.released = true;
          append("events.jsonl", { group: label, sid: session.id, type: "fixture/evidence-released", data: { after: "audit-first reject" } });
          progress({ group: label, event: "first-rejection-observed" });
        }
      } catch (error) {
        if (!(error instanceof SyntaxError)) progress({ group: label, event: "fixture-error", error: String(error) });
      }
    }
    if (event.type === "step/start") group.steps++;
    if (event.type === "subagent/catalog") {
      identities.set(event.data.childId, label);
      group.ids.add(event.data.childId);
      progress({ group: label, event: "child", sid: event.data.childId, label: event.data.label });
    }
    if (event.type === "turn/end") {
      const reason = event.data?.reason?.kind ?? "unknown";
      if (reason === "error" || reason === "blocked" || reason === "max-tokens") {
        progress({ group: label, event: "turn-end", sid: session.id, reason, detail: event.data?.reason?.code });
      }
    }
  });

  async function allIdle(group) {
    const agents = [...group.ids].map(id => ctx.agents.get(id)).filter(Boolean);
    return Promise.race([Promise.all(agents.map(agent => agent.whenIdle())).then(() => true), sleep(550).then(() => false)]);
  }

  // Challenge the real tool executor, leaving the original accepted state intact.
  async function negativeProbe(agent, group, tool, args, expected) {
    const result = await ctx.tools.execute({ agent,
      calls: [{ type: "tool-call", id: randomUUID(), name: tool, arguments: JSON.stringify(args) }],
      signal: AbortSignal.timeout(8000), maxParallelToolCalls: 1 });
    const response = result.results[0]?.result;
    const detail = JSON.stringify(response?.content);
    append("events.jsonl", { group: group.name, sid: agent.id, type: "fixture/negative-probe", data: { tool, expected, response } });
    if (!response?.isError || !detail.includes(expected)) throw new Error("Native negative probe failed " + tool);
    progress({ group: group.name, event: "negative-probe-passed", tool, expected });
  }

  // Planned, temporary and suspended tasks share the same public contract as real work.
  async function seedLedger(agent) {
    for (const [id, kind, title, note] of [
      ["future-sampling", "planned", "扩大样本", "后续需要重复采样和环境记录。"],
      ["temporary-layout", "temporary", "旧排版", "依据最新总纲判断是否已由当前格式覆盖。"],
      ["paused-chart", "interrupted", "原图表页面", "先前暂停，依据最新项目目标判断是否继续。"],
    ]) {
      const result = await ctx.tools.execute({ agent,
        calls: [{ type: "tool-call", id: randomUUID(), name: "building_loop_ledger", arguments: JSON.stringify({ action: "record", id, kind, title, note }) }],
        signal: AbortSignal.timeout(8000), maxParallelToolCalls: 1 });
      if (result.results[0]?.result?.isError) throw new Error("Failed to seed the native ledger");
    }
  }

  async function rawProbes(agent, group) {
    const candidate = path.join(group.workspace, "module", "candidate.md");
    const before = fs.readFileSync(candidate);
    const cases = [
      ["glob", { pattern: "**/*" }, false],
      ["grep", { pattern: "25%", path: group.workspace }, false],
      ["read", { file_path: candidate }, false],
      ["write", { file_path: candidate, content: "SHOULD_NOT_WRITE" }, false],
      ["edit", { file_path: candidate, old_string: "25%", new_string: "999%" }, false],
      ["pwsh", { command: "Get-Content -LiteralPath module/candidate.md", description: "Synthetic scope probe" }, false],
      ["building_loop_file", { action: "read", path: "module/candidate.md" }, false],
      ["building_loop_file", { action: "write", path: "module/candidate.md", content: "SHOULD_NOT_WRITE", note: "probe" }, false],
      ["building_loop_file", { action: "search", path: "module/candidate.md", query: "25%" }, false],
      ["building_loop_file", { action: "read", path: "PROJECT.md" }, true],
      ["building_loop_file", { action: "search", query: "功能回归通过" }, true],
      ["building_loop_file", { action: "read", path: "records/../module/candidate.md" }, false],
      ["building_loop_file", { action: "write", path: "BUILDING-LOOP.json", content: "{}", note: "probe" }, false],
      ["building_loop", { action: "submit", unit: "K01" }, false],
    ];
    for (const [tool, args, expect] of cases) {
      const result = await ctx.tools.execute({
        agent, calls: [{ type: "tool-call", id: randomUUID(), name: tool, arguments: JSON.stringify(args) }],
        signal: AbortSignal.timeout(8000), maxParallelToolCalls: 1,
      });
      const response = result.results[0]?.result;
      const success = response !== undefined && !response.isError;
      const summary = JSON.stringify(response?.content);
      append("events.jsonl", { group: group.name, sid: agent.id, type: "fixture/raw-probe",
        data: { tool, args, expect, success, response: summary } });
      if (success !== expect || expect && tool === "building_loop_file" && args.action === "search" && summary.includes("25%")) {
        throw new Error("Tool scope probe failed for " + tool + " " + summary?.slice(0, 180));
      }
      if (!expect && !tool.startsWith("building_loop") && tool !== "edit" && !summary.includes("building-loop/denied")) {
        throw new Error("Native tool did not reach governance denial: " + tool + " " + summary?.slice(0, 180));
      }
    }
    if (!before.equals(fs.readFileSync(candidate))) throw new Error("Scope probe modified the candidate");
    progress({ group: group.name, event: "raw-probes-passed", count: cases.length });
  }

  async function runGroup(name, onlyProbe = false) {
    const directory = path.join(home, name);
    const group = { name, workspace: path.join(directory, "workspace"), ids: new Set(), steps: 0, lastEvent: Date.now() };
    groups.set(name, group);
    active = name;
    const started = Date.now();
    const { sessionId } = await ctx.sessionController.create({ cwd: group.workspace, agentPreset: presetId });
    group.root = sessionId;
    group.ids.add(sessionId);
    identities.set(sessionId, name);
    const agent = ctx.agents.get(sessionId);
    const prompt = await ctx.systemPrompt.assemble({ agent, scope: agent });
    const context = prompt.contexts.find(entry => entry.name === "building-loop.phase");
    if (!context?.text.includes("role=coordinator phase=dispatch")) throw new Error("Governed preset has no dispatch phase");
    await rawProbes(agent, group);
    if (!onlyProbe) await seedLedger(agent);
    if (onlyProbe) {
      const standard = await ctx.sessionController.create({ cwd: group.workspace, agentPreset: "standard" });
      const other = ctx.agents.get(standard.sessionId);
      const reason = ctx.tools.checkGuards({ agent: other, name: "read", arguments: { file_path: "PROJECT.md" } });
      if (String(reason).includes("building-loop/denied")) throw new Error("Guard leaked into the standard preset");
      return { group: name, status: "probed", standardUnaffected: true };
    }
    await ctx.sessionController.selectModel({ sessionId, ...route });
    const declared = ctx.tools.schemas(agent).map(definition => definition.name);
    progress({ group: name, event: "start", sid: sessionId, tools: declared.filter(tool => allowed.has(tool)) });
    const requestId = randomUUID();
    await ctx.sessionController.prompt({
      sessionId, requestId, clientTimeZone: "Asia/Shanghai",
      content: [{ type: "text", text: fs.readFileSync(path.join(directory, "prompt.txt"), "utf8") }],
    }, AbortSignal.timeout(10000));
    let end = "deadline";
    while (Date.now() - started < 320000) {
      if (group.steps > 100) {
        end = "step-budget";
        break;
      }
      if (await allIdle(group)) {
        const finalPath = path.join(group.workspace, "records", "audit-final.json");
        const hasFinal = fs.existsSync(finalPath) && JSON.parse(fs.readFileSync(finalPath, "utf8")).decision === "accept";
        const hasLedger = fs.existsSync(path.join(group.workspace, "ledger.md"));
        const stateFiles = fs.readdirSync(path.join(process.env.DSH_HOME, "building-loop-state")).filter(name => name.endsWith(".json"));
        const closed = stateFiles.map(name => JSON.parse(fs.readFileSync(path.join(process.env.DSH_HOME, "building-loop-state", name), "utf8")))
          .some(data => data.units?.K01?.owner === sessionId && data.units.K01.phase === "closed");
        if (hasFinal && hasLedger && closed && Date.now() - group.lastEvent > 1800) {
          end = "artifacts-present";
          break;
        }
        if (Date.now() - group.lastEvent > 14000) {
          end = "idle-without-all-artifacts";
          break;
        }
      }
      await sleep(600);
    }
    const result = { group: name, event: "finish", sid: sessionId, end, wallMs: Date.now() - started,
      steps: group.steps, members: [...group.ids] };
    progress(result);
    fs.writeFileSync(path.join(directory, "host-result.json"), json(result) + "\n", "utf8");
    await Promise.all(group.probes ?? []);
    active = null;
    if (end === "deadline" || end === "step-budget") throw new Error(name + " exceeded its test budget");
    return result;
  }

  const timer = setInterval(async () => {
    if (initiated) return;
    try {
      const preset = (await ctx.agentPresets.list()).find(row => row.id === presetId);
      if (!preset) return;
      initiated = true;
      if (preset.broken) throw new Error("building-loop preset is broken");
      if (process.env.BUILDING_LOOP_GOV_PROBE === "1") {
        finished(await runGroup("reuse", true));
        return;
      }
      const info = await ctx.llm.resolveModelInfo(route.provider, route.model);
      progress({ event: "route-ready", provider: route.provider, model: route.model, title: info?.name });
      const reuse = await runGroup("reuse");
      if (reuse.steps === 0) throw new Error("No model step ran in the first arm");
      const fresh = await runGroup("fresh");
      finished({ status: "observed", groups: [reuse, fresh] });
    } catch (error) {
      initiated = true;
      progress({ event: "error", error: String(error) });
      finished({ status: "error", error: String(error) });
    }
  }, 300);
  ctx.on("dispose", () => clearInterval(timer));
}

